INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-game-chess', 'game', 'chess', 'Softcurse''s Chess', 'published', 0, '{"image":"/posters/games/chess.webp","heroImage":"/posters/games/page/chess-page.webp","character":"/posters/games/chess_char.webp","charSize":{"w":300,"h":450},"icon":"♟","tag":"STRATEGY / DARK FANTASY","genre":"Strategy","status":"beta","engine":"Three.js + React","platforms":["Web"],"playUrl":"https://softcurse-chess.pages.dev","shortDesc":"A free-to-play 3D chess experience set on a dark gothic battlefield suspended in the cosmos.","desc":"Step onto a shattered realm drifting through an endless void. Softcurse''s Chess\n    reimagines the classic game as a dark fantasy war — every piece is a hand-crafted 3D model\n    carved from antique stone, the board is a gothic fortress floating in a procedural galaxy,\n    and every capture triggers cinematic battle animations. No downloads, no accounts — the\n    entire experience runs in your browser.","features":["Full 3D Gothic Battlefield","Hand-Crafted Antique Stone Pieces","Player vs AI — 4 Difficulty Tiers","Online PvP via Room Codes","Local PvP — Pass & Play","AI vs AI Spectator Mode","Cinematic Battle Animations","Asset-Based Audio & Ambient Soundscape","Procedural Galaxy Skybox","Mobile & Tablet Ready","Auto-Save & ELO Rating System"],"devBlog":[],"releaseDate":"2026 — Open Beta","version":"beta"}', CURRENT_TIMESTAMP);
