INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-game-hexbrewers', 'game', 'hexbrewers', 'HexBrewers from Ashenveil', 'published', 2, '{"image":"/posters/games/hexbrewers.webp","heroImage":"/posters/games/page/hexbrewers-page.webp","heroPosition":"center","character":"/posters/games/hexbrewers-char.webp","charSize":{"w":320,"h":320},"characterName":"The Brewer''s Bag","icon":"⚗","tag":"BAG-BUILDING / DARK FANTASY","genre":"Strategy","status":"dev","engine":"React + Pixi.js","platforms":["Web"],"ctaLabel":"IN DEVELOPMENT","ctaDisabled":true,"shortDesc":"Brew from a cursed bag, press your luck, and outscore the Shade before the ninth omen falls.","desc":"Build a bag of volatile ingredients and draw them into a spiraling crucible.\n    Every token can strengthen the brew — or push its Voidshards past the breaking point.\n    Survive the omen, score prestige, trade soulstones at the Black Market, and adapt\n    your recipe across nine rounds while the Shade changes strategy against you.","features":["Dark Fantasy Bag-Building Strategy","Nine-Round Omen Campaign","Push-Your-Luck Crucible Brewing","Ingredient Tokens & Recipe Books","Adaptive AI Opponent — The Shade","Black Market Upgrades","Prestige & Soulstone Economy","Pixi.js Particles & Token Animation","English, Georgian & Russian","Reactive Audio & Settings"],"devBlog":[],"releaseDate":"TBA","version":"0.1.0"}', CURRENT_TIMESTAMP);
