INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-game-chronicles', 'game', 'chronicles', 'Chronicles of a Fallen World', 'published', 3, '{"image":"/posters/games/chronicles.webp","heroImage":"/posters/games/page/chronicles-page.webp","character":"/posters/games/chronicles-char.webp","charSize":{"w":300,"h":450},"characterName":"The Auditor","icon":"🌑","tag":"RPG / DARK FANTASY","genre":"RPG","status":"dev","engine":"Unity","platforms":["PC","Console (TBA)"],"shortDesc":"A sprawling dark fantasy RPG in a world teetering on oblivion.","desc":"A sprawling dark fantasy RPG set in a world teetering on the edge of oblivion.\n    Every choice echoes through a fractured realm of crumbling empires, dark gods, and\n    desperate survivors. There are no heroes here — only those who endure.\n    The world remembers everything you do. So do its inhabitants.","features":["Open World Exploration","Branching Narrative","Faction Reputation System","Dynamic Weather & Seasons","Crafting & Alchemy","Co-op Multiplayer (4 players)","Procedural Dungeons","Moral Consequence Engine"],"devBlog":[{"date":"2025-10-28","title":"World-Building Update: The Faction System","excerpt":"The lore just got deeper. A look at faction politics and the consequences of allegiance."},{"date":"2025-09-05","title":"Combat Design Philosophy","excerpt":"Why we built combat around exhaustion rather than health — and why it makes everything better."}],"releaseDate":"TBA","version":"0.7.0-dev"}', CURRENT_TIMESTAMP);
