INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-game-ww3', 'game', 'ww3', 'World War III: Global Collapse', 'published', 5, '{"image":"/posters/games/ww3.webp","heroImage":"/posters/games/page/ww3-page.webp","heroPosition":"center","character":"/posters/games/ww3-char.webp","charSize":{"w":300,"h":300},"icon":"🌍","tag":"STRATEGY / SIMULATION","genre":"Strategy","status":"dev","engine":"Custom Engine","platforms":["PC"],"shortDesc":"Command nations. Manage resources. Prevent — or cause — global annihilation.","desc":"Command nations. Manage resources. Prevent — or cause — global annihilation.\n    A brutal geopolitical strategy simulation where every alliance has a price and\n    every border is negotiable. Victory is not guaranteed. Survival might not be either.\n    The board is the planet. The pieces are nations. The clock is ticking.","features":["Nation Management & Policy","Real-time Conflict System","Diplomacy & Intelligence","Economic Warfare","Nuclear Deterrence Mechanics","Online Multiplayer (Up to 16)","Intelligence & Espionage","Historical Scenarios"],"devBlog":[],"releaseDate":"TBA","version":null}', CURRENT_TIMESTAMP);
