INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-devnotes', 'app', 'devnotes', 'DEVNOTES', 'published', 6, '{"image":"/posters/apps/devnotes.webp","heroImage":"/posters/apps/page/devnotes-page.webp","icon":"📋","tag":"PRODUCTIVITY","status":"active","shortDesc":"All-in-one desktop workspace for developers — tasks, mind maps, AI, and GitHub sync.","desc":"DevNotes is a unified desktop workspace that replaces your scattered tools with a single,\n    purpose-built environment for developers. Manage projects, milestones, and daily standups.\n    Brainstorm architecture with interactive mind maps. Draft with a built-in Claude AI assistant.\n    Sync your encrypted workspace to a private GitHub Gist and work seamlessly across machines.\n    Fast, native, and built to stay out of your way.","features":["Project & Task Management","Interactive Mind Maps","Built-in Claude AI Assistant","GitHub Gist Sync (encrypted)","Google Calendar Integration","AI Standup Drafting & Auto-tagging","System Tray & Global Shortcuts","Native Windows — Rust Backend (Tauri v2)"],"techStack":["React 18","Vite","Zustand","Tauri v2","Rust"],"releaseDate":"2024-06-01","version":"1.3.2"}', CURRENT_TIMESTAMP);
