INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-medialab', 'app', 'medialab', 'Softcurse Media Lab AI', 'published', 7, '{"image":"/posters/apps/medialab.webp","heroImage":"/posters/apps/page/medialab-page.webp","icon":"🤖","tag":"AI TOOL","status":"dev","shortDesc":"Hardware-accelerated AI image editor — watermark removal, inpainting, upscaling, and generative fill.","desc":"Media Lab AI is a hardware-accelerated Windows application for advanced image manipulation\n    and AI-powered media processing. Remove watermarks and objects with LaMa inpainting, strip\n    backgrounds, upscale with ESRGAN, and generate content with Stable Diffusion — all in one\n    cyberpunk-themed workspace. DirectML GPU acceleration works on any GPU, with automatic CPU\n    fallback. Supports batch video watermark removal, audio/video conversion via FFmpeg, and\n    a full toolkit of quick image utilities.","features":["LaMa Inpainting — Object & Watermark Removal","Magic Wand (Segment Anything Model)","AI Background Removal & Upscaling (ESRGAN)","Generative Fill via Stable Diffusion","Video Watermark Removal + Audio Remux","Batch AV Converter (FFmpeg)","Toolkit Lab — Resize, Convert, Crop, Compare","DirectML / CUDA / CPU Acceleration"],"techStack":["WPF",".NET 8","OpenCvSharp4","ONNX Runtime","FFmpeg"],"releaseDate":"2024-01-01","version":"3.0"}', CURRENT_TIMESTAMP);
