INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-archvis', 'app', 'archvis', 'Softcurse Architecture Visualizer', 'published', 8, '{"image":"/posters/apps/arch.webp","heroImage":"/posters/apps/page/arch-page.webp","icon":"🏗️","tag":"DEV TOOL","status":"dev","shortDesc":"Dependency graph visualizer for 13 languages — AST-based analysis, D3.js interactive graphs, 85% accuracy.","desc":"The Architecture Visualizer analyzes and maps the dependency graph of any codebase\n    with 85% average parsing accuracy across 13 programming languages. Deep AST-based analyzers\n    cover Python (100%), Java (95%), C# (95%), and JavaScript/TypeScript (85%). The output is an\n    interactive D3.js graph with zoom, pan, node filtering, and circular dependency detection.\n    81% faster than baseline with 86% less memory usage. Smart caching means only changed files\n    are re-analyzed on subsequent runs.","features":["13 Languages — Python, C#, Java, JS, TS, Go, Rust, PHP, and more","AST-Based Parsing — 85% Average Accuracy","Interactive D3.js Graph with Zoom & Pan","Circular Dependency Detection","Smart Incremental Caching","81% Faster, 86% Less Memory Than Baseline","Force-Directed, Hierarchical & Circular Layouts","Configurable via .visualizer.yml"],"techStack":["Python 3.8+","D3.js","javalang","AST","PyYAML"],"releaseDate":"2025-11-23","version":"2.0.0"}', CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO content_revisions (content_id, revision, action, data_json, created_by) VALUES ('seed-app-archvis', 1, 'seed', '{"image":"/posters/apps/arch.webp","heroImage":"/posters/apps/page/arch-page.webp","icon":"🏗️","tag":"DEV TOOL","status":"dev","shortDesc":"Dependency graph visualizer for 13 languages — AST-based analysis, D3.js interactive graphs, 85% accuracy.","desc":"The Architecture Visualizer analyzes and maps the dependency graph of any codebase\n    with 85% average parsing accuracy across 13 programming languages. Deep AST-based analyzers\n    cover Python (100%), Java (95%), C# (95%), and JavaScript/TypeScript (85%). The output is an\n    interactive D3.js graph with zoom, pan, node filtering, and circular dependency detection.\n    81% faster than baseline with 86% less memory usage. Smart caching means only changed files\n    are re-analyzed on subsequent runs.","features":["13 Languages — Python, C#, Java, JS, TS, Go, Rust, PHP, and more","AST-Based Parsing — 85% Average Accuracy","Interactive D3.js Graph with Zoom & Pan","Circular Dependency Detection","Smart Incremental Caching","81% Faster, 86% Less Memory Than Baseline","Force-Directed, Hierarchical & Circular Layouts","Configurable via .visualizer.yml"],"techStack":["Python 3.8+","D3.js","javalang","AST","PyYAML"],"releaseDate":"2025-11-23","version":"2.0.0"}', 'system');

INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-livescriptor', 'app', 'livescriptor', 'LiveScriptor', 'published', 9, '{"image":"/posters/apps/livescriptor.webp","heroImage":"/posters/apps/page/livescriptor-page.webp","icon":"✍️","tag":"DEV TOOL","status":"dev","shortDesc":"High-performance HTML/CSS/JS live editor with real-time preview, Monaco IntelliSense, and multi-workspace support.","desc":"LiveScriptor is a native Windows live editor built for rapid front-end prototyping.\n    Write HTML, CSS, and JavaScript in a Monaco-powered editor and watch your output render\n    instantly in the dual-pane preview — no browser refresh required. CSS changes inject via\n    DOM diffing without a full reload. Manage entire project folders through the workspace\n    explorer, work across multiple files with tabbed dirty-state tracking, and detach the\n    preview window to a second monitor. IntelliSense, Emmet, and layout persistence included.","features":["Real-Time Preview — No Reload Required","CSS Hot Module Replacement via DOM Diffing","Monaco Editor with True IntelliSense (JS/TS/CSS)","Emmet Abbreviations for HTML","Workspace Explorer — Recursive Folder Loading","Tabbed Interface with Dirty State Tracking","Detachable Preview for Multi-Monitor","Layout & Window Persistence Across Sessions"],"techStack":[".NET 9","Windows Forms","Monaco Editor","WebView2"],"releaseDate":"2024-03-15","version":"2.1.0"}', CURRENT_TIMESTAMP);
