INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-blackwatch', 'app', 'blackwatch', 'Softcurse Blackwatch', 'published', 10, '{"image":"/posters/apps/blackwatch.webp","heroImage":"/posters/apps/page/blackwatch-page.webp","icon":"🔒","tag":"SECURITY","status":"dev","shortDesc":"Anti-cheat and system monitoring suite — real-time threat scoring, process purge, and network visibility.","desc":"Blackwatch is a high-performance Windows security and anti-cheat monitoring solution\n    with a cyberpunk-industrial UI. It scans every 5 seconds across Enumeration, Analysis, and\n    Network Correlation stages, scoring new processes instantly via WMI watcher. A holographic\n    threat sphere turns red when danger is detected. One-click purge terminates all high-severity\n    threats, with a dry-run safety mode to preview before acting. Full network TCP tracking,\n    process explorer with kill controls, and a color-coded live log viewer.","features":["Automated Scanning Every 5 Seconds","Instant WMI Threat Scoring (no gap)","3D Holographic Threat Sphere","One-Click Purge with Dry-Run Mode","Real-Time Network TCP Tracking","Full Process Explorer with Kill Controls","Process Whitelist Manager","Color-Coded Live Log Viewer"],"techStack":["React 18","TypeScript","WPF (.NET 9)","WebView2","Framer Motion"],"releaseDate":"2024-08-10","version":"1.0.5"}', CURRENT_TIMESTAMP);
