INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-spectral', 'app', 'spectral', 'Softcurse Spectral', 'published', 11, '{"image":"/posters/apps/spectral.webp","heroImage":"/posters/apps/page/spectral-page.webp","icon":"👁️","tag":"UTILITY","status":"dev","shortDesc":"Wi-Fi and network optimization suite — real-time monitoring, channel analysis, one-click optimization, and router integration.","desc":"Spectral is a premium Wi-Fi and network optimization suite for Windows and macOS.\n    Monitor live RSSI, throughput, and latency. Deep-scan 2.4 GHz, 5 GHz, and 6 GHz bands\n    for channel congestion, then apply one-click optimizations — power management, DNS benchmarking,\n    TCP auto-tuning, and roaming suppression — with a single UAC prompt and full rollback support.\n    Auto-detects ASUS and TP-Link routers and applies the best channel automatically.\n    CLI mode available for scripting and automation.","features":["Live RSSI, Throughput & Latency Monitoring","Spectrum Scan — 2.4 / 5 / 6 GHz Channel Congestion","One-Click Optimization with Suggestion Preview","Full Rollback to Original Settings","ASUS & TP-Link Router Auto-Integration","DNS Benchmark — Cloudflare, Google, Quad9","TCP Auto-Tuning & Power Management","CLI Mode + macOS (Apple Silicon & Intel)"],"techStack":[".NET 8","WPF","Avalonia UI 11.1","React Native (Expo)","ManagedNativeWifi"],"releaseDate":"2026-01-01","version":"5.0.0"}', CURRENT_TIMESTAMP);
