INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-inkmind', 'app', 'inkmind', 'Softcurse InkMind', 'published', 12, '{"image":"/posters/apps/inkmind.webp","heroImage":"/posters/apps/page/inkmind-page.webp","icon":"🧠","tag":"AI / WRITING","status":"dev","shortDesc":"AI-powered creative writing environment — chapter generation, context memory, world-building, and native TTS.","desc":"InkMind is a full-featured creative writing environment with deep AI integration.\n    Generate 1000+ word chapters using Full Context — characters, world bible, key events, and\n    author rules all injected automatically. The Tandem Workflow drafts, critiques, and polishes\n    in one loop. AI Entity Extraction scans text to auto-populate your character and world database.\n    The Inquisitor checks consistency. The Sadistic Editor ruthlessly cuts weak paragraphs.\n    Native Silero TTS reads chapters aloud offline. Zero-latency editor handles 10,000+ word chapters\n    without slowdown.","features":["AI Chapter Generation with Full Context Injection","Tandem Workflow — Draft → Critique → Polish","AI Entity Extraction for Characters & World","The Inquisitor — Consistency Checker","Native Silero TTS (Offline)","Zero-Latency Editor for 10,000+ Word Chapters","Smart Import — DOCX, PDF, EPUB, TXT, Markdown","Export for Publisher, Editor, or Audio"],"techStack":["Python 3.10","Tkinter","Gemini API","Silero TTS","OpenRouter"],"releaseDate":"2025-01-01","version":"1.1.0"}', CURRENT_TIMESTAMP);
