INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-ytdl', 'app', 'ytdl', 'Softcurse YT Downloader', 'published', 13, '{"image":"/posters/apps/ytdl.webp","heroImage":"/posters/apps/page/ytdl-page.webp","icon":"⬇️","tag":"UTILITY","status":"dev","shortDesc":"YouTube to MP3/MP4 downloader with playlist support, quality selection, and cyberpunk UI.","desc":"A clean, fast YouTube downloader with a cyberpunk neon UI. Download audio at\n    128–320 kbps MP3 or video at up to 1080p MP4 — your choice, your quality. Paste any\n    YouTube URL, pick your format and output folder, and hit download. Playlist mode grabs\n    entire playlists in one click. Real-time neon progress bar shows speed and ETA. Auto-installs\n    yt-dlp on first launch. Ships as a standalone .exe — no Python required on target machines.","features":["MP3 Mode — 128 / 192 / 256 / 320 kbps","MP4 Mode — Best / 1080p / 720p / 480p / 360p","Playlist Mode — Full Playlist in One Click","Real-Time Neon Progress Bar with Speed & ETA","Auto-Installs yt-dlp on First Launch","Remembers Last Folder & Quality Settings","Builds to Standalone .exe (no Python needed)","FFmpeg Integration for MP3 Conversion & MP4 Merge"],"techStack":["Python 3.10","tkinter","yt-dlp","FFmpeg"],"releaseDate":"2023-11-01","version":"3.0.1"}', CURRENT_TIMESTAMP);
