INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-vault', 'app', 'vault', 'Softcurse Vault Cleaner', 'published', 14, '{"image":"/posters/apps/vault.webp","heroImage":"/posters/apps/page/vault-page.webp","icon":"🧹","tag":"UTILITY","status":"active","shortDesc":"Windows disk cleanup and analyzer — browser caches, system junk, duplicate finder, and one-click purge.","desc":"Vault Cleaner is an advanced Windows disk cleanup and analysis utility. Clean\n    browser caches (Chrome, Edge, Firefox, Brave), Windows Update leftovers, NVIDIA and\n    Unreal Engine caches, Python PIP, Android SDK images, event logs, orphaned installers,\n    and more — all with real-time progress tracking and detailed logs. The Disk Analyzer\n    deep-scans any drive to surface storage hogs, list the largest files, find duplicates\n    by MD5 hash, and map installed program sizes. Send identified junk directly to the\n    cleanup protocol with one click.","features":["15+ Cleanup Targets — Browser, System, GPU, Dev Tools","Disk Analyzer — Deep Scan Any Drive","Duplicate Finder via MD5 Hash","Large File Discovery with One-Click Location","Program Sizer — Space Per Installed App","Quick Scan — Estimate Space Before Cleanup","DISM Component Store Cleanup with ResetBase","Full Operation Logging to %LOCALAPPDATA%"],"techStack":["WPF",".NET 8","C# 10","MVVM","System.Management"],"releaseDate":"2023-09-20","version":"2.3"}', CURRENT_TIMESTAMP);
