INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-gela', 'app', 'gela', 'GELA', 'published', 15, '{"image":"/posters/apps/gela.png","heroImage":"/posters/apps/gela.png","icon":"◉","tag":"VOICE CONTROL","status":"dev","shortDesc":"Offline Georgian voice control for Windows — private, precise, and built around safe commands.","desc":"GELA is an offline-first Georgian voice controller for Windows. It listens for a fixed\n    wake phrase, recognizes short Georgian or English commands, and controls allowlisted applications,\n    games, media, windows, and selected system actions. Speech recognition and ordinary computer control\n    stay on the PC. GELA is deliberately a command tool, not a conversational assistant, and rejects\n    uncertain instructions instead of guessing.","features":["Offline Georgian Wake Phrase and Command Recognition","Safe Application and Steam Game Control","Window, Media, Volume, and Fixed System Actions","Aliases, Routines, Diagnostics, and Voice Calibration","System Tray Controls and Silent Windows Startup","Authenticated Bridge for the GELA Mobile Companion","Optional Private-Network Access through Tailscale","No Arbitrary Shell Execution or Passive Cloud Uploads"],"techStack":["Python 3.11+","Vosk","Omnilingual ASR","sherpa-onnx","PyInstaller","Windows"],"releaseDate":"2026-08-01","version":"1.5.2"}', CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO content_revisions (content_id, revision, action, data_json, created_by) VALUES ('seed-app-gela', 1, 'seed', '{"image":"/posters/apps/gela.png","heroImage":"/posters/apps/gela.png","icon":"◉","tag":"VOICE CONTROL","status":"dev","shortDesc":"Offline Georgian voice control for Windows — private, precise, and built around safe commands.","desc":"GELA is an offline-first Georgian voice controller for Windows. It listens for a fixed\n    wake phrase, recognizes short Georgian or English commands, and controls allowlisted applications,\n    games, media, windows, and selected system actions. Speech recognition and ordinary computer control\n    stay on the PC. GELA is deliberately a command tool, not a conversational assistant, and rejects\n    uncertain instructions instead of guessing.","features":["Offline Georgian Wake Phrase and Command Recognition","Safe Application and Steam Game Control","Window, Media, Volume, and Fixed System Actions","Aliases, Routines, Diagnostics, and Voice Calibration","System Tray Controls and Silent Windows Startup","Authenticated Bridge for the GELA Mobile Companion","Optional Private-Network Access through Tailscale","No Arbitrary Shell Execution or Passive Cloud Uploads"],"techStack":["Python 3.11+","Vosk","Omnilingual ASR","sherpa-onnx","PyInstaller","Windows"],"releaseDate":"2026-08-01","version":"1.5.2"}', 'system');

INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-gela-mobile', 'app', 'gela-mobile', 'GELA Mobile', 'published', 16, '{"image":"/posters/apps/gela-mobile.webp","heroImage":"/posters/apps/gela-mobile.webp","icon":"⌁","tag":"MOBILE COMPANION","status":"dev","shortDesc":"Android command deck for securely controlling a paired GELA Windows PC.","desc":"GELA Mobile is the Android companion to GELA for Windows. It sends short voice or typed\n    commands to a paired PC over local Wi-Fi or an encrypted private network. The app supports multiple\n    computers, secure token storage, local rediscovery, deliberate file and clipboard exchange, and\n    time-limited view-only screen access. It never acts as a general remote desktop and keeps the PC as\n    the final authorization boundary.","features":["Six-Digit Pairing with Secure Token Storage","Georgian Voice and Typed PC Commands","Multiple Saved PCs with Local Rediscovery","Local Wi-Fi and Private Tailscale Connectivity","Explicit File and Clipboard Exchange","Biometric Confirmation for Sensitive Actions","Time-Limited, View-Only PC Screen Access","Independent Georgian and English Interface Languages"],"techStack":["React Native 0.86","Expo SDK 57","TypeScript","Android","SecureStore"],"releaseDate":"2026-08-01","version":"1.0.0"}', CURRENT_TIMESTAMP);
