INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-app-codex-pixel', 'app', 'codex-pixel', 'Codex Pixel', 'published', 17, '{"image":"/posters/apps/codex-pixel.jpg","heroImage":"/posters/apps/codex-pixel.jpg","icon":"▦","tag":"DEVELOPER TOOL","status":"dev","shortDesc":"A living pixel workspace that turns Codex agent activity into an animated visual world.","desc":"Codex Pixel is a Softcurse developer-tool project that makes coding-agent work visible.\n    Active Codex sessions appear as pixel characters inside a customizable workspace, with movement and\n    animation reflecting their current activity. The project explores Codex-aware session detection,\n    themed environments, character states, and a playful interface for understanding parallel development\n    work at a glance.","features":["Codex-Aware Agent Activity Visualization","Animated Pixel Characters and Live Status States","Custom Softcurse Visual Themes and Environments","Interactive Workspace Layout","Multiple Simultaneous Agent Sessions","VS Code and Standalone Workspace Exploration"],"techStack":["TypeScript","React 19","Vite","Canvas 2D","VS Code Webview","Fastify"],"releaseDate":"2026-08-01"}', CURRENT_TIMESTAMP);
