INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-experiment-sebas', 'experiment', 'sebas', 'S.E.B.A.S', 'published', 18, '{"image":"/posters/experiments/sebas.webp","icon":"🜄","tag":"AUTONOMOUS AI","status":"dev","shortDesc":"A fully local autonomous system assistant — voice control, deep OS integration, skill forge, and an Empire architecture that grows with every command.","desc":"S.E.B.A.S (Stage 3: The Empire) is a fully local, modular autonomous assistant\n    that lives inside your machine — not in a cloud, not on a server. It binds to your OS,\n    speaks when spoken to, and builds new skills when commanded. The Empire Model organizes\n    it into Archons (Speech, Vision, Knowledge, Integration), Generals (LLM, STT, TTS),\n    and a ForgeMaster that generates new abilities from voice commands alone.\n    Shadow Memory via RAG means it remembers everything you''ve ever told it.\n    It does not need the internet. It does not report home. It obeys one master.","features":["Empire Architecture — Emperor, Archons, Generals, Wardens","The Forge — generates new skills from voice commands via LLM","Shadow Memory (RAG) — persistent knowledge across all sessions","Intent Weaving Engine — tone, semantics, context, history parsing","Voice Bindings — fully configurable TTS and STT pipeline","REST Gate — authenticated API for external automations","Self-Healing Watchers — auto-restarts dead services","Multi-provider LLM — OpenAI, Gemini, Ollama, OpenRouter, Grok"],"techStack":["Python","LangChain","SQLite","Telegram Bot API","FastAPI","Whisper STT","Coqui TTS"],"releaseDate":null,"version":"3.0-empire"}', CURRENT_TIMESTAMP);
