INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-localization-blasphemous-georgian', 'localization', 'blasphemous-georgian', 'Blasphemous — Georgian Localization', 'published', 19, '{"image":"/posters/localization/blasphemous-georgian.png","heroImage":"/posters/localization/blasphemous-georgian.png","icon":"Ⴕ","tag":"TRANSLATION MOD","status":"dev","shortDesc":"An unofficial Georgian translation mod with a custom Gothic Georgian typeface and a complete static text corpus.","desc":"An unofficial, fan-made Georgian localization for Blasphemous. The project translates\n    interface text, dialogue, items, quests, locations, achievements, DLC content, cutscenes, and\n    system messages while preserving the game’s variables and formatting tokens. A custom Georgian\n    font pipeline was built to keep the original Gothic atmosphere readable in Mkhedruli. All static\n    text entries are translated; full-game visual QA and release packaging are still in progress.","features":["1,879 of 1,879 Static Localization Entries Translated","Custom Gothic Georgian Mkhedruli Typeface","Interface, Dialogue, Items, Quests, DLC, and Cutscenes","Automated Key, Token, and Formatting Validation","Runtime Loader and Localization-Specific UI Fixes","Structured Full-Game Visual QA Matrix","Release Packaging and Final Runtime Verification in Progress"],"techStack":["Georgian Localization",".NET","BepInEx","HarmonyX","Unity Asset Pipeline"],"version":"0.1.0","progress":"Static text complete · Visual QA in progress","disclaimer":"Blasphemous is created by The Game Kitchen. This is an unofficial fan localization and is not affiliated with or endorsed by the game’s creators or publishers."}', CURRENT_TIMESTAMP);
