INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-chronicle-black-ledger', 'chronicle', 'black-ledger', 'The Black Ledger', 'published', 20, '{"series":"Chronicles of the Fallen World","book":"Book IV","image":"/posters/chronicles/cotf/pt1/black-ledger.webp","heroImage":"/posters/chronicles/cotf/pt1/black-ledger-page.webp","character":"/posters/chronicles/cotf/pt1/black-ledger-char.webp","characterName":"The Auditor","charSize":{"w":300,"h":450},"genre":"Dark Fantasy","platforms":["Chronicles"],"engine":"Multi-POV Narrative","status":"dev","tag":"DARK FANTASY","releaseDate":"TBA","version":null,"shortDesc":"A debt is never truly paid. The Auditor has come to collect what was promised — and the city of Ash will remember the price.","desc":"Set 1,000 years after the events of Books I–III, The Black Ledger opens in an Ash City\n    that has rebuilt itself on the bones of the old world — and on the debts it never repaid.\n    The Auditor arrives not as a conqueror, but as a collector. What follows is a reckoning\n    told through the eyes of those who owe, those who survived, and those who built the new\n    order on the silence of the fallen. This is not a war story. It is an accounting.","features":["Multi-POV narrative — same events from different eyes","Interactive chapter visualization","Character relationship mapping","Timeline tracking across perspectives"],"devBlog":[],"chapters":[{"num":1,"title":"The Price of Dawn","file":"/chronicles/black-ledger/pt1/chapter-01.html","status":"published"},{"num":2,"title":"The Gardener of Dead Flowers","file":"/chronicles/black-ledger/pt1/chapter-02.html","status":"published"},{"num":3,"title":"Architecture of Silence","file":"/chronicles/black-ledger/pt1/chapter-03.html","status":"published"},{"num":4,"title":"Mechanics of Flesh","file":"/chronicles/black-ledger/pt1/chapter-04.html","status":"published"},{"num":5,"title":"Liturgy of Steel","file":"/chronicl