INSERT OR IGNORE INTO content_items (id, type, slug, title, status, sort_order, data_json, published_at) VALUES ('seed-chronicle-empire-of-shadows', 'chronicle', 'empire-of-shadows', 'Empire of Shadows', 'published', 21, '{"series":"Chronicles of the Fallen World","book":"Book IV","image":"/posters/chronicles/cotf/pt2/black-ledger_pt2.webp","heroImage":"/posters/chronicles/cotf/pt2/black-ledger_pt2-page.webp","character":"/posters/chronicles/cotf/pt2/black-ledger-char2.webp","characterName":"The Auditor","charSize":{"w":300,"h":450},"genre":"Dark Fantasy","platforms":["Chronicles"],"engine":"Multi-POV Narrative","status":"dev","tag":"DARK FANTASY","releaseDate":"TBA","version":null,"shortDesc":"The ledger is closed. The empire remains. The Auditor''s work is far from over.","desc":"The second POV volume of Book IV. Where The Black Ledger counted the cost,\n    Empire of Shadows maps the architecture of what was built on those bones.\n    The Auditor moves deeper into the power structure of Ash City — not as a collector now,\n    but as something the city cannot yet name.","features":["Multi-POV narrative — same events from different eyes","Interactive chapter visualization","Character relationship mapping","Timeline tracking across perspectives"],"devBlog":[],"chapters":[{"num":1,"title":"Dead Capital","file":"/chronicles/black-ledger/pt2/chapter-01.html","status":"published"},{"num":2,"title":"Black Registry","file":"/chronicles/black-ledger/pt2/chapter-02.html","status":"published"},{"num":3,"title":"Sovereign Debt","file":"/chronicles/black-ledger/pt2/chapter-03.html","status":"published"},{"num":4,"title":"The Bonesmasher","file":"/chronicles/black-ledger/pt2/chapter-04.html","status":"published"},{"num":5,"title":"Inventory","file":"/chronicles/black-ledger/pt2/chapter-05.html","status":"published"},{"num":6,"title":"Audit of a Deity","file":"/chronicles/black-ledger/pt2/chapter-06.html","status":"published"},{"num":7,"title":"Technical Specification: Sarcophagus","file":"/chronicles/black-ledger/pt2/chapter-07.html","status":"published"},{"num":8,"title":"Assimilation Protocol","file":"/chronicles/black-ledger/pt2/chapter-08.html","status":"published"},{"num":9,"title":"Operator of the Abyss","file":"/chronicles/black-ledger/pt2/chapter-09.html","status":"published"}]}', CURRENT_TIMESTAMP);
